window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-414d335e0682cbac"]={"versions": [{"id": "FIG-414d335e0682cbac", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Evaluierungs- und Variantensets innerhalb des AUTOSAR Generic Structure Template (GST). Das Diagramm spezifiziert die Struktur zur Aggregation und Zuordnung von vordefinierten Varianten, Systemeinstellungskonstanten und Post-Build-Kriterien zu bewerteten Modellelementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>EvaluatedVariantSet</code> (Spezialisierung von <code>ARElement</code>): Besitzt das Attribut <code>+ approvalStatus: NameToken</code>. Referenziert über die gerichtete Assoziation <code>+evaluatedVariant</code> mit Multiplizität <code>0..<em></code> die Zielklasse <code>PredefinedVariant</code> und über <code>+evaluatedElement</code> mit Multiplizität <code>0..</em></code> die Zielklasse <code>ElementCollection::CollectableElement</code> (spezialisiert <code>Identifiable</code>).</li>\n<li><code>PredefinedVariant</code> (Spezialisierung von <code>ARElement</code>): Besitzt eine reflexive Assoziation <code>+includedVariant</code> (<code>0..<em></code>). Referenziert über <code>+swSystemconstantValueSet</code> (<code>0..</em></code>) die Klasse <code>SwSystemconstantValueSet</code> und über <code>+postBuildVariantCriterionValueSet</code> (<code>0..*</code>) die Klasse <code>PostBuildVariantCriterionValueSet</code>.</li>\n<li><code>SwSystemconstantValueSet</code> (Spezialisierung von <code>ARElement</code>): Komponiert über <code>+swSystemconstantValue</code> mit Multiplizität <code>0..*</code> Instanzen von <code>SwSystemconstValue</code>.</li>\n<li><code>SwSystemconstValue</code>: Enthält das variierte Attribut <code>+ value: Numerical</code> unter dem Stereotyp <code>«atpVariation»</code>. Referenziert über die gerichtete Assoziation <code>+swSystemconst</code> mit Multiplizität <code>1</code> die Klasse <code>SystemConstant::SwSystemconst</code> (Spezialisierung von <code>ARElement</code>).</li>\n<li><code>PostBuildVariantCriterionValueSet</code> (Spezialisierung von <code>ARElement</code>): Komponiert über <code>+postBuildVariantCriterionValue</code> mit Multiplizität <code>0..*</code> Instanzen von <code>PostBuildVariantCriterionValue</code>.</li>\n<li><code>PostBuildVariantCriterionValue</code>: Enthält das variierte Attribut <code>+ value: Integer</code> unter dem Stereotyp <code>«atpVariation»</code>. Referenziert über die gerichtete Assoziation <code>+variantCriterion</code> mit Multiplizität <code>1</code> die Klasse <code>PostBuildVariantCriterion</code> (Spezialisierung von <code>ARElement</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die deklarative Struktur zur Auswertung von Variantenkonfigurationen. Zur Auflösung werden einem <code>EvaluatedVariantSet</code> mehrere <code>PredefinedVariant</code>-Instanzen zugeordnet, die ihrerseits über Wertemengen (<code>SwSystemconstantValueSet</code>, <code>PostBuildVariantCriterionValueSet</code>) konkrete Bindungen von Systemkonstanten (<code>SwSystemconstValue</code>) und Post-Build-Kriterien (<code>PostBuildVariantCriterionValue</code>) für die referenzierten <code>CollectableElement</code>-Instanzen vorgeben.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung von Metaklassen des AUTOSAR-Standards. Alle Wurzelelemente (<code>EvaluatedVariantSet</code>, <code>PredefinedVariant</code>, <code>SwSystemconstantValueSet</code>, <code>PostBuildVariantCriterionValueSet</code>, <code>SystemConstant::SwSystemconst</code>, <code>PostBuildVariantCriterion</code>) sind als <code>ARElement</code> eigenständig im Modell adressierbar (ShortName-Pfad). <code>approvalStatus</code> dient der formalen Freigabekennzeichnung des Bewertungssatzes. Variation Points auf den Attributwerten (<code>«atpVariation»</code>) unterliegen den AUTOSAR-Regeln für modellbasierte Varianzbindung.</p>"}, {"id": "FIG-ce9469580f339b82", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Evaluierungs- und Variantensets innerhalb des AUTOSAR Generic Structure Template (GST). Das Diagramm spezifiziert die Struktur zur Aggregation und Zuordnung von vordefinierten Varianten, Systemeinstellungskonstanten und Post-Build-Kriterien zu bewerteten Modellelementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>EvaluatedVariantSet</code> (Spezialisierung von <code>ARElement</code>): Besitzt das Attribut <code>+ approvalStatus :NameToken</code>. Referenziert über die gerichtete Assoziation <code>+evaluatedVariant</code> mit Multiplizität <code>0..<em></code> die Zielklasse <code>PredefinedVariant</code> und über <code>+evaluatedElement</code> mit Multiplizität <code>0..</em></code> die Zielklasse <code>CollectableElement</code> (spezialisiert <code>Identifiable</code>).</li>\n<li><code>PredefinedVariant</code> (Spezialisierung von <code>ARElement</code>): Besitzt eine reflexive Assoziation <code>+includedVariant</code> (<code>0..<em></code>). Referenziert über <code>+swSystemconstantValueSet</code> (<code>0..</em></code>) die Klasse <code>SwSystemconstantValueSet</code> und über <code>+postBuildVariantCriterionValueSet</code> (<code>0..*</code>) die Klasse <code>PostBuildVariantCriterionValueSet</code>.</li>\n<li><code>SwSystemconstantValueSet</code> (Spezialisierung von <code>ARElement</code>): Komponiert über <code>+swSystemconstantValue</code> mit Multiplizität <code>0..*</code> Instanzen von <code>SwSystemconstValue</code>.</li>\n<li><code>SwSystemconstValue</code>: Enthält das variierte Attribut <code>+ value :Numerical</code> unter dem Stereotyp <code>«atpVariation»</code>. Referenziert über die gerichtete Assoziation <code>+swSystemconst</code> mit Multiplizität <code>1</code> die Klasse <code>SwSystemconst</code> (Spezialisierung von <code>ARElement</code> und <code>AtpDefinition</code>).</li>\n<li><code>PostBuildVariantCriterionValueSet</code> (Spezialisierung von <code>ARElement</code>): Komponiert über <code>+postBuildVariantCriterionValue</code> mit Multiplizität <code>0..*</code> Instanzen von <code>PostBuildVariantCriterionValue</code>.</li>\n<li><code>PostBuildVariantCriterionValue</code>: Enthält das variierte Attribut <code>+ value :Integer</code> unter dem Stereotyp <code>«atpVariation»</code>. Referenziert über die gerichtete Assoziation <code>+variantCriterion</code> mit Multiplizität <code>1</code> die Klasse <code>PostBuildVariantCriterion</code> (Spezialisierung von <code>ARElement</code> und <code>AtpDefinition</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die deklarative Struktur zur Auswertung von Variantenkonfigurationen. Zur Auflösung werden einem <code>EvaluatedVariantSet</code> mehrere <code>PredefinedVariant</code>-Instanzen zugeordnet, die ihrerseits über Wertemengen (<code>SwSystemconstantValueSet</code>, <code>PostBuildVariantCriterionValueSet</code>) konkrete Bindungen von Systemkonstanten (<code>SwSystemconstValue</code>) und Post-Build-Kriterien (<code>PostBuildVariantCriterionValue</code>) für die referenzierten <code>CollectableElement</code>-Instanzen vorgeben.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung von Metaklassen des AUTOSAR-Standards. Alle Wurzelelemente (<code>EvaluatedVariantSet</code>, <code>PredefinedVariant</code>, <code>SwSystemconstantValueSet</code>, <code>PostBuildVariantCriterionValueSet</code>, <code>SwSystemconst</code>, <code>PostBuildVariantCriterion</code>) sind als <code>ARElement</code> eigenständig im Modell adressierbar; <code>SwSystemconst</code> und <code>PostBuildVariantCriterion</code> sind zusätzlich als Definitionsbestandteile (<code>AtpDefinition</code>) deklariert. <code>approvalStatus</code> dient der formalen Freigabekennzeichnung des Bewertungssatzes. Variation Points auf den Attributwerten (<code>«atpVariation»</code>) unterliegen den AUTOSAR-Regeln für modellbasierte Varianzbindung.</p>"}, {"id": "FIG-2fcef26ecfd9b1da", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Evaluierungs- und Variantensets innerhalb des AUTOSAR Generic Structure Template (GST). Das Diagramm spezifiziert die Struktur zur Aggregation und Zuordnung von vordefinierten Varianten, Systemeinstellungskonstanten und Post-Build-Kriterien zu bewerteten Modellelementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>EvaluatedVariantSet</code> (Spezialisierung von <code>ARElement</code>): Besitzt das Attribut <code>+ approvalStatus :NameToken</code>. Referenziert über die gerichtete Assoziation <code>+evaluatedVariant</code> mit Multiplizität <code>0..<em></code> die Zielklasse <code>PredefinedVariant</code> und über <code>+evaluatedElement</code> mit Multiplizität <code>0..</em></code> die Zielklasse <code>CollectableElement</code> (spezialisiert <code>Identifiable</code>).</li>\n<li><code>PredefinedVariant</code> (Spezialisierung von <code>ARElement</code>): Besitzt eine reflexive Assoziation <code>+includedVariant</code> (<code>0..<em></code>). Referenziert über <code>+swSystemconstantValueSet</code> (<code>0..</em></code>) die Klasse <code>SwSystemconstantValueSet</code> und über <code>+postBuildVariantCriterionValueSet</code> (<code>0..*</code>) die Klasse <code>PostBuildVariantCriterionValueSet</code>.</li>\n<li><code>SwSystemconstantValueSet</code> (Spezialisierung von <code>ARElement</code>): Komponiert über <code>+swSystemconstantValue</code> mit Multiplizität <code>0..*</code> Instanzen von <code>SwSystemconstValue</code>.</li>\n<li><code>SwSystemconstValue</code>: Enthält das variierte Attribut <code>+ value :Numerical</code> unter dem Stereotyp <code>«atpVariation»</code>. Referenziert über die gerichtete Assoziation <code>+swSystemconst</code> mit Multiplizität <code>1</code> die Klasse <code>SwSystemconst</code> (Spezialisierung von <code>ARElement</code> und <code>AtpDefinition</code>).</li>\n<li><code>PostBuildVariantCriterionValueSet</code> (Spezialisierung von <code>ARElement</code>): Komponiert über <code>+postBuildVariantCriterionValue</code> mit Multiplizität <code>0..*</code> Instanzen von <code>PostBuildVariantCriterionValue</code>.</li>\n<li><code>PostBuildVariantCriterionValue</code>: Enthält das variierte Attribut <code>+ value :Integer</code> unter dem Stereotyp <code>«atpVariation»</code>. Referenziert über die gerichtete Assoziation <code>+variantCriterion</code> mit Multiplizität <code>1</code> die Klasse <code>PostBuildVariantCriterion</code> (Spezialisierung von <code>ARElement</code> und <code>AtpDefinition</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die deklarative Struktur zur Auswertung von Variantenkonfigurationen. Zur Auflösung werden einem <code>EvaluatedVariantSet</code> mehrere <code>PredefinedVariant</code>-Instanzen zugeordnet, die ihrerseits über Wertemengen (<code>SwSystemconstantValueSet</code>, <code>PostBuildVariantCriterionValueSet</code>) konkrete Bindungen von Systemkonstanten (<code>SwSystemconstValue</code>) und Post-Build-Kriterien (<code>PostBuildVariantCriterionValue</code>) für die referenzierten <code>CollectableElement</code>-Instanzen vorgeben.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung von Metaklassen des AUTOSAR-Standards. Alle Wurzelelemente (<code>EvaluatedVariantSet</code>, <code>PredefinedVariant</code>, <code>SwSystemconstantValueSet</code>, <code>PostBuildVariantCriterionValueSet</code>, <code>SwSystemconst</code>, <code>PostBuildVariantCriterion</code>) sind als <code>ARElement</code> eigenständig im Modell adressierbar; <code>SwSystemconst</code> und <code>PostBuildVariantCriterion</code> sind zusätzlich als Definitionsbestandteile (<code>AtpDefinition</code>) deklariert. <code>approvalStatus</code> dient der formalen Freigabekennzeichnung des Bewertungssatzes. Variation Points auf den Attributwerten (<code>«atpVariation»</code>) unterliegen den AUTOSAR-Regeln für modellbasierte Varianzbindung.</p>"}, {"id": "FIG-2816a837729b6f6a", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Evaluierungs- und Variantensets innerhalb des AUTOSAR Generic Structure Template (GST). Das Diagramm spezifiziert die Struktur zur Aggregation und Zuordnung von vordefinierten Varianten, Systemeinstellungskonstanten und Post-Build-Kriterien zu bewerteten Modellelementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>EvaluatedVariantSet</code> (Spezialisierung von <code>ARElement</code>): Besitzt das Attribut <code>+ approvalStatus :NameToken</code>. Referenziert über die gerichtete Assoziation <code>+evaluatedVariant</code> mit Multiplizität <code>0..<em></code> die Zielklasse <code>PredefinedVariant</code> und über <code>+evaluatedElement</code> mit Multiplizität <code>0..</em></code> die Zielklasse <code>CollectableElement</code> (spezialisiert <code>Identifiable</code>).</li>\n<li><code>PredefinedVariant</code> (Spezialisierung von <code>ARElement</code>): Besitzt eine reflexive Assoziation <code>+includedVariant</code> (<code>0..<em></code>). Referenziert über <code>+swSystemconstantValueSet</code> (<code>0..</em></code>) die Klasse <code>SwSystemconstantValueSet</code> und über <code>+postBuildVariantCriterionValueSet</code> (<code>0..*</code>) die Klasse <code>PostBuildVariantCriterionValueSet</code>.</li>\n<li><code>SwSystemconstantValueSet</code> (Spezialisierung von <code>ARElement</code>): Komponiert über <code>+swSystemconstantValue</code> mit Multiplizität <code>0..*</code> Instanzen von <code>SwSystemconstValue</code>.</li>\n<li><code>SwSystemconstValue</code>: Enthält das variierte Attribut <code>+ value :Numerical</code> unter dem Stereotyp <code>«atpVariation»</code>. Referenziert über die gerichtete Assoziation <code>+swSystemconst</code> mit Multiplizität <code>1</code> die Klasse <code>SwSystemconst</code> (Spezialisierung von <code>ARElement</code> und <code>AtpDefinition</code>).</li>\n<li><code>PostBuildVariantCriterionValueSet</code> (Spezialisierung von <code>ARElement</code>): Komponiert über <code>+postBuildVariantCriterionValue</code> mit Multiplizität <code>0..*</code> Instanzen von <code>PostBuildVariantCriterionValue</code>.</li>\n<li><code>PostBuildVariantCriterionValue</code>: Enthält das variierte Attribut <code>+ value :Integer</code> unter dem Stereotyp <code>«atpVariation»</code>. Referenziert über die gerichtete Assoziation <code>+variantCriterion</code> mit Multiplizität <code>1</code> die Klasse <code>PostBuildVariantCriterion</code> (Spezialisierung von <code>ARElement</code> und <code>AtpDefinition</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die deklarative Struktur zur Auswertung von Variantenkonfigurationen. Zur Auflösung werden einem <code>EvaluatedVariantSet</code> mehrere <code>PredefinedVariant</code>-Instanzen zugeordnet, die ihrerseits über Wertemengen (<code>SwSystemconstantValueSet</code>, <code>PostBuildVariantCriterionValueSet</code>) konkrete Bindungen von Systemkonstanten (<code>SwSystemconstValue</code>) und Post-Build-Kriterien (<code>PostBuildVariantCriterionValue</code>) für die referenzierten <code>CollectableElement</code>-Instanzen vorgeben.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung von Metaklassen des AUTOSAR-Standards. Alle Wurzelelemente (<code>EvaluatedVariantSet</code>, <code>PredefinedVariant</code>, <code>SwSystemconstantValueSet</code>, <code>PostBuildVariantCriterionValueSet</code>, <code>SwSystemconst</code>, <code>PostBuildVariantCriterion</code>) sind als <code>ARElement</code> eigenständig im Modell adressierbar; <code>SwSystemconst</code> und <code>PostBuildVariantCriterion</code> sind zusätzlich als Definitionsbestandteile (<code>AtpDefinition</code>) deklariert. <code>approvalStatus</code> dient der formalen Freigabekennzeichnung des Bewertungssatzes. Variation Points auf den Attributwerten (<code>«atpVariation»</code>) unterliegen den AUTOSAR-Regeln für modellbasierte Varianzbindung.</p>"}, {"id": "FIG-bf67b4e53277537d", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Evaluierungs- und Variantensets innerhalb des AUTOSAR Generic Structure Template (GST). Das Diagramm spezifiziert die Struktur zur Aggregation und Zuordnung von vordefinierten Varianten, Systemeinstellungskonstanten und Post-Build-Kriterien zu bewerteten Modellelementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>EvaluatedVariantSet</code> (Spezialisierung von <code>ARElement</code>): Besitzt das Attribut <code>+ approvalStatus: NameToken</code>. Referenziert über die gerichtete Assoziation <code>+evaluatedVariant</code> mit Multiplizität <code>0..<em></code> die Zielklasse <code>PredefinedVariant</code> und über <code>+evaluatedElement</code> mit Multiplizität <code>0..</em></code> die Zielklasse <code>CollectableElement</code> (spezialisiert <code>Identifiable</code>).</li>\n<li><code>PredefinedVariant</code> (Spezialisierung von <code>ARElement</code>): Besitzt eine reflexive Assoziation <code>+includedVariant</code> (<code>0..<em></code>). Referenziert über <code>+swSystemconstantValueSet</code> (<code>0..</em></code>) die Klasse <code>SwSystemconstantValueSet</code> und über <code>+postBuildVariantCriterionValueSet</code> (<code>0..*</code>) die Klasse <code>PostBuildVariantCriterionValueSet</code>.</li>\n<li><code>SwSystemconstantValueSet</code> (Spezialisierung von <code>ARElement</code>): Komponiert über <code>+swSystemconstantValue</code> mit Multiplizität <code>0..*</code> Instanzen von <code>SwSystemconstValue</code>.</li>\n<li><code>SwSystemconstValue</code>: Enthält das variierte Attribut <code>+ value: Numerical</code> unter dem Stereotyp <code>«atpVariation»</code>. Referenziert über die gerichtete Assoziation <code>+swSystemconst</code> mit Multiplizität <code>1</code> die Klasse <code>SwSystemconst</code> (Spezialisierung von <code>ARElement</code> und <code>AtpDefinition</code>).</li>\n<li><code>PostBuildVariantCriterionValueSet</code> (Spezialisierung von <code>ARElement</code>): Komponiert über <code>+postBuildVariantCriterionValue</code> mit Multiplizität <code>0..*</code> Instanzen von <code>PostBuildVariantCriterionValue</code>.</li>\n<li><code>PostBuildVariantCriterionValue</code>: Enthält das variierte Attribut <code>+ value: Integer</code> unter dem Stereotyp <code>«atpVariation»</code>. Referenziert über die gerichtete Assoziation <code>+variantCriterion</code> mit Multiplizität <code>1</code> die Klasse <code>PostBuildVariantCriterion</code> (Spezialisierung von <code>ARElement</code> und <code>AtpDefinition</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die deklarative Struktur zur Auswertung von Variantenkonfigurationen. Zur Auflösung werden einem <code>EvaluatedVariantSet</code> mehrere <code>PredefinedVariant</code>-Instanzen zugeordnet, die ihrerseits über Wertemengen (<code>SwSystemconstantValueSet</code>, <code>PostBuildVariantCriterionValueSet</code>) konkrete Bindungen von Systemkonstanten (<code>SwSystemconstValue</code>) und Post-Build-Kriterien (<code>PostBuildVariantCriterionValue</code>) für die referenzierten <code>CollectableElement</code>-Instanzen vorgeben.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung von Metaklassen des AUTOSAR-Standards. Alle Wurzelelemente (<code>EvaluatedVariantSet</code>, <code>PredefinedVariant</code>, <code>SwSystemconstantValueSet</code>, <code>PostBuildVariantCriterionValueSet</code>, <code>SwSystemconst</code>, <code>PostBuildVariantCriterion</code>) sind als <code>ARElement</code> eigenständig im Modell adressierbar; <code>SwSystemconst</code> und <code>PostBuildVariantCriterion</code> sind zusätzlich als Definitionsbestandteile (<code>AtpDefinition</code>) deklariert. <code>approvalStatus</code> dient der formalen Freigabekennzeichnung des Bewertungssatzes. Variation Points auf den Attributwerten (<code>«atpVariation»</code>) unterliegen den AUTOSAR-Regeln für modellbasierte Varianzbindung.</p>"}], "trans": [{"from": "FIG-414d335e0682cbac", "to": "FIG-ce9469580f339b82", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>CollectableElement</code>: Paketpräfix <code>ElementCollection::</code> entfernt.</li>\n<li><code>SwSystemconst</code>: Paketpräfix <code>SystemConstant::</code> entfernt; zusätzlich als <code>«AtpDefinition»</code> typisiert.</li>\n<li><code>PostBuildVariantCriterion</code>: Zusätzlich als <code>«AtpDefinition»</code> typisiert.</li>\n<li><code>EvaluatedVariantSet</code>: Leerzeichen vor dem Doppelpunkt im Attribut <code>+ approvalStatus :NameToken</code> eingefügt.</li>\n<li><code>SwSystemconstValue</code>: Leerzeichen vor dem Doppelpunkt im Attribut <code>+ value :Numerical</code> eingefügt.</li>\n<li><code>PostBuildVariantCriterionValue</code>: Leerzeichen vor dem Doppelpunkt im Attribut <code>+ value :Integer</code> eingefügt.</li>\n</ul>"}, {"from": "FIG-ce9469580f339b82", "to": "FIG-2fcef26ecfd9b1da", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2fcef26ecfd9b1da", "to": "FIG-2816a837729b6f6a", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2816a837729b6f6a", "to": "FIG-bf67b4e53277537d", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>EvaluatedVariantSet</code>: Leerzeichen vor dem Doppelpunkt im Attribut <code>+ approvalStatus: NameToken</code> entfernt.</li>\n<li><code>SwSystemconstValue</code>: Leerzeichen vor dem Doppelpunkt im Attribut <code>+ value: Numerical</code> entfernt.</li>\n<li><code>PostBuildVariantCriterionValue</code>: Leerzeichen vor dem Doppelpunkt im Attribut <code>+ value: Integer</code> entfernt.</li>\n<li><code>CollectableElement</code>: Name kursiv gesetzt (<em>CollectableElement</em>).</li>\n<li><code>ARElement</code> und <code>AtpDefinition</code>: Stereotypen bzw. Meta-Klassifizierungen in den Kopfbereichen der Klassen kursiv gesetzt (<em>ARElement</em>, <em>AtpDefinition</em>).</li>\n</ul>"}]};
